import{_ as i,c as t,o as n,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"PRESERVING AND PROTECTING THE INTEGRITY OF AMERICAN ELECTIONS","description":"","frontmatter":{"title":"PRESERVING AND PROTECTING THE INTEGRITY OF AMERICAN ELECTIONS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/preserving-and-protecting-the-integrity-of-american-elections/","publishDate":"2025-03-25T16:17:34-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-25-preserving-and-protecting-the-integrity-of-american-elections.md","filePath":"executive-orders/2025-03-25-preserving-and-protecting-the-integrity-of-american-elections.md"}'),o={name:"executive-orders/2025-03-25-preserving-and-protecting-the-integrity-of-american-elections.md"};function a(s,e,l,c,g,p){return n(),t("div",null,e[0]||(e[0]=[r('<h1 id="preserving-and-protecting-the-integrity-of-american-elections" tabindex="-1">PRESERVING AND PROTECTING THE INTEGRITY OF AMERICAN ELECTIONS <a class="header-anchor" href="#preserving-and-protecting-the-integrity-of-american-elections" aria-label="Permalink to &quot;PRESERVING AND PROTECTING THE INTEGRITY OF AMERICAN ELECTIONS&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/preserving-and-protecting-the-integrity-of-american-elections/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/preserving-and-protecting-the-integrity-of-american-elections/</a></p><p>Published: 2025-03-25T16:17:34-04:00</p><ul><li><p><strong>Election Protection Enforcement</strong></p><ul><li>The U.S. lacks essential election protections compared to other countries.</li><li>Emphasizes the need for free, fair, and honest elections vital for democracy.</li><li>States must align with federal laws to ensure election integrity.</li></ul></li><li><p><strong>Voter Eligibility</strong></p><ul><li>Requires proof of U.S. citizenship on voter registration forms.</li><li>Provides guidelines for States to verify voter citizenship using federal databases.</li><li>Demands the Attorney General to prioritize enforcement against non-citizen voting.</li></ul></li><li><p><strong>Voting Equipment and Integrity</strong></p><ul><li>Promotes uniform voting standards, including a voter-verifiable paper record.</li><li>Mandates an audit of voting system certifications.</li><li>States failing to comply with federal guidelines may face funding consequences.</li></ul></li><li><p><strong>Federal Compliance and Enforcement</strong></p><ul><li>Emphasizes the need for states to adhere to federal laws regarding voting and election day procedures.</li><li>Outlines potential penalties for states not cooperating with federal election integrity measures.</li></ul></li><li><p><strong>Protection Against Foreign Influence</strong></p><ul><li>Reinforces prohibitions on foreign participation and funding in elections.</li><li>Calls for enforcement of laws against foreign donations and lobbying in U.S. elections.</li></ul></li><li><p><strong>Overall Compliance</strong></p><ul><li>Requires agencies to submit compliance reports.</li><li>Ensures that any invalid provisions of the order do not affect the remainder.</li><li>Clarifies that the order does not create enforceable rights against the U.S. government.</li></ul></li></ul>',4)]))}const u=i(o,[["render",a]]);export{f as __pageData,u as default};
